// 6300

/* Prompt, read a line and parse it into verb and noun numbers. The first word must be a verb and
the second a noun; an unknown word prints "I DONT KNOW HOW TO <word> SOMETHING" (or "... <verb> A
<noun>") by copying the words into the message text, and asks again. A blank second word looks up
as N_NONE (eight spaces is in the noun table). */

void read_command(void)

{
  
  cmd_unused = 0;
  print_prompt();
  get_line();
  next_word();
  lookup_word(&verb_table);
  if (word_id == 0xff) {
    rt_copy(8, &word_buf, &unknown_verb_text);
    rt_print("I DONT KNOW HOW TO          SOMETHING\r");
    read_command();
    return;
  }
  verb = word_id;
  rt_copy(8, &word_buf, &verb_word);
  next_word();
  lookup_word(&noun_table);
  if (word_id != 0xff) {
    noun = word_id;
    rt_copy(8, &word_buf, &noun_word);
    return;
  }
  rt_copy(8, &verb_word, &unknown_noun_verb);
  rt_copy(8, &word_buf, &unknown_noun_text);
  rt_print("I DONT KNOW HOW TO          A         \r");
  read_command();
  return;
}


